$models = Get-Content "backend/src/main/kotlin/com/attendance/server/models/AttendanceModels.kt" -Raw
$models = $models -replace "(?s)object AttendanceRecords : Table\(\`"attendance_records\`"\) \{.*?\}", "object AttendanceRecords : Table(`"attendance_records`") {`n    val id = uuid(`"id`").autoGenerate()`n    val sessionId = uuid(`"session_id`").references(AttendanceSessions.id)`n    val studentId = uuid(`"student_id`").references(Users.id)`n    val successfulChecks = integer(`"successful_checks`")`n    val lastDetectedAt = timestamp(`"last_detected_at`")`n    val overrideStatus = varchar(`"override_status`", 50).nullable()`n    val finalStatus = varchar(`"final_status`", 50).nullable()`n    val hasCheckoutScan = bool(`"has_checkout_scan`").default(false)`n    val reviewReason = varchar(`"review_reason`", 255).nullable()`n    override val primaryKey = PrimaryKey(id)`n}"
Set-Content "backend/src/main/kotlin/com/attendance/server/models/AttendanceModels.kt" $models
